void config_material(uint32_t i, channels::rock_v1_material &g) {
  switch (i) {
    case 0: config_material_basalt(g); return;
    case 1: config_material_granite(g); return;
    case 2: config_material_limestone(g); return;
    case 3: config_material_marble(g); return;
    case 4: config_material_obsidian(g); return;
    case 5: config_material_riverstone(g); return;
    case 6: config_material_sandstone(g); return;
    case 7: config_material_slate(g); return;
  }
}

struct Built final : runtime::Build {
  decltype(channels::rock_v1_model::pieces) body_pieces;
};

struct State final : runtime::PoseState {
  channels::rock_v1_motion animate_in;
  channels::rock_v1_pose animate_out;
};

template <typename T>
void key_add(uint64_t &h, const T &v) { h = runtime::fnv64(&v, sizeof v, h); }

class Type final : public runtime::PipelineType {
 public:
  const char *name() const override { return "rock_v1"; }
  size_t params_size() const override { return sizeof(Params); }
  size_t event_count() const override { return 1; }
  bool has_update() const override { return true; }
  const std::vector<runtime::StageInfo> &stages() const override {
    static const std::vector<runtime::StageInfo> s = {{"rock_v1.body", false}, {"rock_v1.animate", true}};
    return s;
  }

  uint64_t build_key(const void *params) const override {
    const Params &p = *static_cast<const Params *>(params);
    uint64_t h = runtime::fnv64("rock_v1", 7);
    key_add(h, p.material);
    key_add(h, p.size);
    key_add(h, p.moss);
    key_add(h, p.season);
    key_add(h, p.seed);
    key_add(h, p.detail);
    return h ? h : 1;
  }

  std::shared_ptr<runtime::Build> build(const void *params, std::string &error) const override {
    const Params &p = *static_cast<const Params *>(params);
    auto b = std::make_shared<Built>();
    const float *clocks = nullptr;
    (void)clocks;
    // body: rock_body_v1
    channels::rock_v1_spec body_in;
    config_material(static_cast<uint32_t>(p.material), body_in.material);
    body_in.size = static_cast<uint32_t>(p.size);
    body_in.moss = static_cast<uint32_t>(p.moss);
    body_in.season = static_cast<uint32_t>(p.season);
    body_in.seed = p.seed;
    body_in.detail = static_cast<uint32_t>(p.detail);
    channels::rock_v1_model body_out;
    {
      const auto t0 = std::chrono::steady_clock::now();
      if (!rock_body_v1::run(body_in, body_out, error)) {
        error = "body (rock_body_v1): " + error;
        return nullptr;
      }
      b->stage_ms.push_back(ms_since(t0));
    }
    b->body_pieces = body_out.pieces;
    {
      std::vector<uint8_t> bytes;
      b->bytes += sizeof(b->body_pieces[0]) * b->body_pieces.size();
      foundry::pack(body_out, bytes);
      b->model_hash = runtime::fnv64(bytes.data(), bytes.size());
    }
    b->mesh.positions = std::move(body_out.positions);
    b->mesh.normals = std::move(body_out.normals);
    b->mesh.colors = std::move(body_out.colors);
    b->mesh.indices = std::move(body_out.indices);
    b->mesh.bone_a = std::move(body_out.bone_a);
    b->mesh.bone_b = std::move(body_out.bone_b);
    b->mesh.bone_w = std::move(body_out.bone_w);
    const auto &m = b->mesh;
    b->triangles = static_cast<uint32_t>(m.indices.size() / 3);
    uint32_t bones = 1;
    for (size_t i = 0; i < m.bone_a.size(); ++i) bones = std::max(bones, m.bone_a[i] + 1);
    for (size_t i = 0; i < m.bone_b.size(); ++i) bones = std::max(bones, m.bone_b[i] + 1);
    b->bones = bones;
    float top = 0;
    bool finite = true;
    for (const auto &v : m.positions) {
      top = std::max(top, v.y);
      finite = finite && std::isfinite(v.x) && std::isfinite(v.y) && std::isfinite(v.z);
    }
    float r2 = 0;
    for (const auto &v : m.positions) {
      const float dy = v.y - top * 0.5f;
      r2 = std::max(r2, v.x * v.x + dy * dy + v.z * v.z);
    }
    b->height = top;
    b->radius = std::sqrt(r2);
    if (!finite) b->problem = "a vertex is not finite";
    else if (m.indices.empty()) b->problem = "the mesh has no triangles";
    else if (*std::max_element(m.indices.begin(), m.indices.end()) >= m.positions.size()) b->problem = "an index is out of range";
    return b;
  }

  std::unique_ptr<runtime::PoseState> bind(const runtime::Build &build) const override {
    const Built &b = static_cast<const Built &>(build);
    (void)b;
    auto s = std::make_unique<State>();
    s->stage_ms.assign(1, 0.0);
    s->matrices.assign(size_t(b.bones) * 16, 0.0f);
    for (uint32_t i = 0; i < b.bones; ++i)
      for (int k = 0; k < 4; ++k) s->matrices[size_t(i) * 16 + k * 5] = 1.0f;
    s->animate_in.pieces = b.body_pieces;
    return s;
  }

  bool update(const runtime::Build &build, runtime::PoseState &state, const void *params, const float *clocks,
              std::string &error) const override {
    const Params &p = *static_cast<const Params *>(params);
    (void)p;
    (void)clocks;
    (void)build;
    State &s = static_cast<State &>(state);
    s.animate_in.break_time = clocks[1];
    s.animate_in.break_heading = p.break_heading;
    s.animate_in.seed = p.seed;
    {
      const auto t0 = std::chrono::steady_clock::now();
      if (!rock_animate_v1::run(s.animate_in, s.animate_out, error)) {
        error = "animate (rock_animate_v1): " + error;
        return false;
      }
      s.stage_ms[0] = ms_since(t0);
    }
    std::swap(s.matrices, s.animate_out.matrices);  // both keep their capacity
    s.settled = s.animate_out.settled;
    return true;
  }

  uint64_t pose_hash(const runtime::PoseState &state) const override {
    const State &s = static_cast<const State &>(state);
    channels::rock_v1_pose out = s.animate_out;
    out.matrices = s.matrices;
    std::vector<uint8_t> bytes;
    foundry::pack(out, bytes);
    return runtime::fnv64(bytes.data(), bytes.size());
  }
};

const Type kType;

bool valid(const Params &p) {
  if (static_cast<uint32_t>(p.material) >= 8u) return false;
  if (static_cast<uint32_t>(p.size) >= 4u) return false;
  if (static_cast<uint32_t>(p.moss) >= 3u) return false;
  if (static_cast<uint32_t>(p.season) >= 4u) return false;
  if (p.seed < 1u || p.seed > 1000u) return false;
  if (static_cast<uint32_t>(p.detail) >= 3u) return false;
  if (!std::isfinite(p.break_heading) || p.break_heading < 0.0f || p.break_heading > 0x1.6800000000000p+8f) return false;
  return true;
}

