void foundry_rock_v1_default_params(Params *params) {
  Params p;
  std::memset(&p, 0, sizeof p);
  p.material = static_cast<foundry_rock_v1_material>(1);
  p.size = static_cast<foundry_rock_v1_size>(1);
  p.moss = static_cast<foundry_rock_v1_moss>(0);
  p.season = static_cast<foundry_rock_v1_season>(2);
  p.seed = 1u;
  p.detail = static_cast<foundry_rock_v1_detail>(0);
  p.break_heading = 0x1.6800000000000p+6f;
  *params = p;
}

foundry_instance foundry_rock_v1_spawn(foundry_runtime *rt, const Params *params, const float transform[16]) {
  if (!rt || !params || !valid(*params)) return FOUNDRY_NO_INSTANCE;
  return rt->world.spawn(&kType, params, transform);
}

foundry_status foundry_rock_v1_set_material(foundry_runtime *rt, foundry_instance instance, foundry_rock_v1_material value) {
  Params check;
  foundry_rock_v1_default_params(&check);
  check.material = value;
  if (!valid(check)) return FOUNDRY_STATUS_BAD_PARAMETER;
  return foundry_status_of(rt->world.set_param(instance, &kType, offsetof(Params, material), &value, sizeof value, true));
}

